// Katze auf den Daechern (nur Spiel-API). Umgesetzt: p1 Springen, p2 Fischgraeten, p3 Luecken und Neustart, p5 Tempo.
// Nicht umgesetzt (ehrlich): p4 (gestreifter Schwanz, gruene Augen: nur das Emoji 🐱 ist moeglich),
// p6 (Ergebnisanzeige nach dem Spiel mit bestem Stand: fehlt).
// Luecken 40 bis 80 px statt 120: bei Tempo 2 ist der Sprung (ca. 37 Frames Flug) sonst nicht schaffbar.
const ROOF_Y = 400, RUN_END = 900;

export default {
  title: "Katze auf den Dächern",
  controls: ["up"],
  lives: 3,

  init(g) {
    const s = { cat: null, roofs: [], fish: 0, held: false, safe: 0 };
    reset(s, g);
    return s;
  },

  update(s, input, g) {
    const c = s.cat;
    if (s.safe > 0) s.safe -= 1;

    // Welt scrollt nach links
    const sp = 2 + 0.5 * (g.level - 1);
    for (const r of s.roofs) r.x -= sp;
    s.roofs = s.roofs.filter((r) => r.x + r.w > -4);
    let last = 0;
    for (const r of s.roofs) last = Math.max(last, r.x + r.w);
    fill(s, g, last);

    // Auf einem Dach bleiben, nur solange es unter der Katze liegt
    if (c.ground && !onRoof(s, c)) c.ground = false;

    // Sprung nur vom Dach und nur beim Druecken (nicht beim Halten)
    if (input.up && !s.held && c.ground) { c.vy = -11; c.ground = false; g.sound("jump"); }
    s.held = !!input.up;

    if (!c.ground) {
      const prev = c.y + c.h;
      c.vy = Math.min(c.vy + 0.6, 14);
      c.y += c.vy;
      for (const r of s.roofs) {
        if (c.vy >= 0 && c.x + c.w > r.x && c.x < r.x + r.w && prev <= r.y && c.y + c.h >= r.y) {
          c.y = r.y - c.h; c.vy = 0; c.ground = true; break;
        }
      }
    }

    // Fischgraeten einsammeln (kein Leben-Verlust)
    for (const r of s.roofs) {
      if (!r.f) continue;
      const fish = { x: r.x + r.w / 2 - 9, y: r.y - 18, w: 18, h: 18 };
      if (g.hit(c, fish)) { r.f = false; s.fish += 1; g.addScore(1); g.sound("coin"); }
    }

    // Sturz durch eine Luecke: ein Leben, Neustart an der Startposition
    if (c.y > g.H) {
      if (s.safe === 0) g.loseLife();
      reset(s, g);
      return;
    }

    if ((g.frame + 1) % 600 === 0) { g.nextLevel(); g.sound("level"); }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.roofs) {
      d.rect(r.x, r.y, r.w, 16, "yellow", { round: 6, shadow: true, line: true });
      if (r.f) d.emoji("🐟", r.x + r.w / 2, r.y - 9, 18);
    }
    const c = s.cat;
    d.emoji("🐱", c.x + c.w / 2, c.y + c.h / 2, 30);
    d.text("Fischgräten: " + s.fish, 12, g.H - 16, { size: 20, align: "left" });
  }
};

function reset(s, g) {
  s.cat = { x: 40, y: ROOF_Y - 30, w: 26, h: 30, vy: 0, ground: true };
  s.fish = 0;
  s.safe = 60;
  s.roofs = [];
  for (let x = 0; x < RUN_END; x += 150) s.roofs.push({ x, y: ROOF_Y, w: 150, f: x % 300 === 0 });
  fill(s, g, RUN_END);
}

function fill(s, g, last) {
  while (last < g.W + 60) {
    const r = addRoof(s, g, last + g.randInt(40, 80));
    last = r.x + r.w;
  }
}

function addRoof(s, g, x) {
  const r = { x, y: g.randInt(360, 440), w: g.randInt(90, 150), f: g.random() < 0.5 };
  s.roofs.push(r);
  return r;
}

function onRoof(s, c) {
  return s.roofs.some((r) => Math.abs(r.y - (c.y + c.h)) < 0.5 && c.x + c.w > r.x && c.x < r.x + r.w);
}

// Katze auf den Daechern: Jump and Run ueber Daecher, Fischgraeten sammeln, Luecke = Lauf vorbei.
// Nicht umgesetzt: Ende-Anzeige mit Fischgraeten-Zahl und Neustart-Knopf (p6, nicht machbar).
const SCROLL = 3, GAP = 50, ROOF_Y = 600, ROOF_H = 40;

export default {
  title: "Katze auf den Dächern",
  controls: ["left", "right", "fire"],
  lives: 1,

  init(g) {
    return {
      me: { x: 30, y: 576, w: 24, h: 24, vx: 0, vy: 0, ground: true },
      roofs: [
        { x: 0, y: ROOF_Y, w: 120, h: ROOF_H },
        { x: 170, y: ROOF_Y, w: 120, h: ROOF_H },
        { x: 340, y: ROOF_Y, w: 140, h: ROOF_H },
        { x: 530, y: ROOF_Y, w: 130, h: ROOF_H },
        { x: 700, y: ROOF_Y, w: 160, h: ROOF_H }
      ],
      fische: [{ x: 100, y: 552, got: false }],
      scroll: 0
    };
  },

  update(s, input, g) {
    const me = s.me;
    me.vx = input.left ? -3 : input.right ? 3 : 0;
    me.x = g.clamp(me.x + me.vx, 0, g.W - me.w);

    // Daecher und Fische scrollen nach links; neue Daecher rechts nachliefern
    for (const r of s.roofs) r.x -= SCROLL;
    for (const f of s.fische) f.x -= SCROLL;
    s.scroll += SCROLL;
    s.roofs = s.roofs.filter((r) => r.x + r.w > -10);
    s.fische = s.fische.filter((f) => f.x > -30 && !f.got);
    let last = s.roofs[s.roofs.length - 1];
    while (last.x + last.w < g.W + 60) {
      const x = last.x + last.w + GAP, w = g.randInt(80, 160);
      last = { x, y: ROOF_Y, w, h: ROOF_H };
      s.roofs.push(last);
      if (g.random() < 0.5) s.fische.push({ x: x + 30, y: 552, got: false });
    }

    const feet = () => me.y + me.h;

    // Sprung
    if ((input.fire || input.firePressed) && me.ground) {
      me.vy = -10; me.ground = false; g.sound("jump");
    }

    // Auf dem Dach bleiben nur, solange noch ein Dach unter den Fuessen ist
    if (me.ground) {
      const on = s.roofs.some((r) => me.x + me.w > r.x && me.x < r.x + r.w && r.y === feet());
      if (!on) { me.ground = false; me.vy = 0; }
    }

    // Schwerkraft und Landung von oben
    me.vy = Math.min(me.vy + 0.5, 12);
    const oldBottom = feet();
    me.y += me.vy;
    if (me.vy >= 0) {
      for (const r of s.roofs) {
        const over = me.x + me.w > r.x && me.x < r.x + r.w;
        if (over && oldBottom <= r.y && feet() >= r.y) { me.y = r.y - me.h; me.vy = 0; me.ground = true; }
      }
    }

    // Fischgraeten einsammeln
    for (const f of s.fische) {
      if (!f.got && g.hit({ x: f.x, y: f.y, w: 24, h: 36 }, { x: me.x, y: me.y, w: me.w, h: me.h })) {
        f.got = true; g.addScore(1); g.sound("coin");
      }
    }
    s.fische = s.fische.filter((f) => !f.got);

    // Gefallen: Lauf vorbei
    if (me.y > g.H) { g.sound("hurt"); g.loseLife(); return; }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.roofs) {
      d.rect(r.x, r.y, r.w, r.h, "yellow", { round: 6, line: true });
      for (let bx = r.x + 8; bx < r.x + r.w - 14; bx += 24) {
        const c = Math.floor(bx / 24) % 2 ? "red" : "ink";
        d.rect(bx, r.y + 6, 14, 8, c, { round: 2 });
        d.rect(bx + 12, r.y + 20, 14, 8, c === "red" ? "ink" : "red", { round: 2 });
      }
    }
    for (const f of s.fische) d.emoji("🐟", f.x + 12, f.y + 12, 24);
    d.emoji("🐈", s.me.x + 12, s.me.y + 12, 30);
  }
};

// Segelboot-Wellen im Hafen (nur Spiel-API). Holzboote wandern in Reihen, Wasserbomben stoppen sie.
export default {
  title: "Segelboot-Wellen im Hafen",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    return { ship: { x: g.W / 2 - 20, y: 580, w: 40, h: 30 }, bombs: [], boats: fleet(g), drift: [], effekte: [], dir: -1, cool: 0, step: 0 };
  },

  update(s, input, g) {
    const ship = s.ship;
    if (input.left) ship.x -= 4;
    if (input.right) ship.x += 4;
    ship.x = g.clamp(ship.x, 4, g.W - 44);

    if (s.cool > 0) s.cool -= 1;
    if ((input.firePressed || input.fire) && s.cool === 0 && s.bombs.length < 3) {
      s.bombs.push({ x: ship.x + 20, y: ship.y, r: 7 });
      s.cool = 14;
      g.sound("shoot");
    }
    for (const b of s.bombs) b.y -= 8;
    s.bombs = s.bombs.filter((b) => b.y >= g.TOP);

    // Holzboote: seitwaerts, am Rand umkehren und eine Reihe tiefer
    const speed = 0.5 + 0.2 * g.level + (24 - s.boats.length) * 0.04;
    let edge = false;
    for (const b of s.boats) {
      b.x += s.dir * speed;
      if ((s.dir < 0 && b.x < 6) || (s.dir > 0 && b.x + b.w > g.W - 6)) edge = true;
    }
    if (edge) { s.dir = -s.dir; for (const b of s.boats) b.y += 14; }

    // Die Flotte rueckt auch ohne Treffer langsam vor (sonst wuerde sie nie das Ufer erreichen)
    s.step += 1;
    if (s.step >= 28) { s.step = 0; for (const b of s.boats) b.y += 14; }

    // Beruehrung des Segelboots oder untere Grenze beendet die Runde
    for (const b of s.boats) {
      if (b.y + b.h >= 560 || g.hit(ship, b)) { g.gameOver(); return; }
    }

    // Treffer: Bombe versenkt das Boot, es treibt weg
    for (const bomb of s.bombs) {
      for (const b of s.boats) {
        if (!b.sunk && g.hit(bomb, b)) {
          b.sunk = true;
          bomb.y = -100;
          g.addScore(1);
          g.sound("pop");
          s.drift.push({ x: b.x, y: b.y, w: b.w, h: b.h, t: 60 });
          s.effekte.push({ x: b.x + b.w / 2, y: b.y + b.h / 2, t: 10 });
          break;
        }
      }
    }
    s.bombs = s.bombs.filter((b) => b.y >= g.TOP);
    s.boats = s.boats.filter((b) => !b.sunk);

    for (const d of s.drift) { d.x -= 0.6; d.y += 1; d.t -= 1; }
    s.drift = s.drift.filter((d) => d.t > 0 && d.y < g.H);
    for (const e of s.effekte) e.t -= 1;
    s.effekte = s.effekte.filter((e) => e.t > 0);

    // Welle geschafft: naechste, schnellere Welle
    if (s.boats.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.boats = fleet(g);
      s.dir = -1;
      s.bombs = [];
      s.step = 0;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let y = 120; y < g.H; y += 60) d.line(0, y + (g.frame >> 3) % 6, g.W, y + (g.frame >> 3) % 6, "yellow", 2);
    for (const b of s.boats) d.emoji("🛶", b.x + b.w / 2, b.y + b.h / 2, 30);
    for (const t of s.drift) {
      d.rect(t.x, t.y, t.w, t.h, "red", { round: 8 });
      d.emoji("🛶", t.x + t.w / 2, t.y + t.h / 2, 20);
    }
    for (const e of s.effekte) {
      d.circle(e.x, e.y, 4 + (10 - e.t), "yellow");
      d.circle(e.x + 3, e.y - 3, 3 + (10 - e.t) / 2, "red");
    }
    for (const b of s.bombs) {
      d.circle(b.x, b.y, 11, "yellow");
      d.emoji("💧", b.x, b.y, 22);
    }
    d.emoji("⛵", s.ship.x + 20, s.ship.y + 15, 36);
  }
};

function fleet(g) {
  const out = [];
  const rows = Math.min(2 + g.level, 5);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < 6; c++) out.push({ x: 20 + c * 52, y: g.TOP + 20 + r * 42, w: 34, h: 30, sunk: false });
  }
  return out;
}

// Katze auf den Daechern: Jump and Run ueber Daecher, Fischgraeten sammeln, Luecken sind toedlich.
const GRAV = 0.5, CAT = 26, CATX = 60, SPRUNG = -9, BOOST = 14;

export default {
  title: "Katze auf den Dächern",
  controls: ["fire"],
  lives: 1,

  init(g) {
    return {
      cat: { x: CATX, y: 534, vy: 0, ground: true, boost: 0 },
      roofs: [{ x: 0, y: 560, w: 360 }],
      bones: [{ x: 180, y: 538, r: 11 }],
      scroll: 2
    };
  },

  update(s, input, g) {
    const c = s.cat;

    // Sprung und Hochhalten (langer Druck springt hoeher)
    if (input.firePressed && c.ground) {
      c.vy = SPRUNG; c.boost = BOOST; c.ground = false; g.sound("jump");
    } else if (input.fire && c.boost > 0 && c.vy < 0) {
      c.vy -= 0.45; c.boost -= 1;
    } else {
      c.boost = 0;
    }

    // Schwerkraft und Bewegung
    const feet = c.y + CAT;
    c.vy = Math.min(c.vy + GRAV, 12);
    c.y += c.vy;
    c.ground = false;
    if (c.vy >= 0) {
      for (const r of s.roofs) {
        if (feet <= r.y + 0.01 && c.y + CAT >= r.y && c.x + CAT > r.x && c.x < r.x + r.w) {
          c.y = r.y - CAT; c.vy = 0; c.ground = true; c.boost = 0;
          break;
        }
      }
    }

    // Neue Daecher und Graeten rechts anlegen
    let last = 0;
    for (const r of s.roofs) if (r.x + r.w > last) last = r.x + r.w;
    while (last < g.W + 20) {
      const x = last + g.randInt(50, 95);
      const w = g.randInt(90, 170);
      const y = g.randInt(440, 580);
      s.roofs.push({ x, y, w });
      if (g.random() < 0.5) s.bones.push({ x: x + w / 2, y: y - 22, r: 11 });
      last = x + w;
    }

    // Scrollen nach links
    const sc = 2 + 0.3 * g.level;
    for (const r of s.roofs) r.x -= sc;
    for (const b of s.bones) b.x -= sc;
    s.roofs = s.roofs.filter((r) => r.x + r.w >= 0);

    // Graeten einsammeln
    const katze = { x: c.x, y: c.y, w: CAT, h: CAT };
    s.bones = s.bones.filter((b) => {
      if (g.hit(katze, b)) { g.addScore(1); g.sound("coin"); return false; }
      return b.x > -20;
    });

    // Level alle 600 Frames
    if (g.frame > 0 && g.frame % 600 === 0) { g.nextLevel(); g.sound("level"); }

    // Fallen in eine Luecke
    if (c.y > g.H) { g.sound("hurt"); g.loseLife(); }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.roofs) d.rect(r.x, r.y, r.w, 24, "yellow", { round: 8, line: true });
    for (const b of s.bones) d.emoji("🐟", b.x, b.y, 22);
    d.emoji("🐱", s.cat.x + CAT / 2, s.cat.y + CAT / 2, 28);
  }
};
